def main():
    source=A/'cosmology-epilogue-character-01-return'
    audit=A/'COSMOLOGY_EPILOGUE_CHARACTER_01_SEMANTIC_AUDIT_01.json'
    root=A/'cosmology-epilogue-character-01-corrections';archive=A/'DD_Cosmology_Epilogue_Character_01_Corrections.zip'
    assert all(not p.exists() for p in [audit,root,archive])
    check=json.loads((A/'COSMOLOGY_EPILOGUE_CHARACTER_01_RETURN_SOURCE_CHECK_01.json').read_bytes())
    assert check['checkCount']==366 and check['failureCount']==1
    model=json.loads((source/'EPILOGUE_CHARACTER_MODEL.json').read_bytes());cases=json.loads((source/'CASEBOOK.json').read_bytes())
    assert len(model['EPI04']['classRows'])==17 and len(model['EPI02']['motifs'])==7 and len(model['EPI06']['test']['scenes'])==7 and len(cases['cases'])==51
    # The replacement puzzle is a finite new design suggestion, not a source claim.
    truth=[]
    for door in [1,2,3]:
        statements=[door==2,door!=2,door!=1]
        truth.append({'door':door,'statements':statements,'trueCount':sum(statements)})
    assert [r['door'] for r in truth if r['trueCount']==1]==[1]
    now=datetime.now(timezone.utc).isoformat()
    audit.write_bytes(encoded({'reviewId':'COSMOLOGY-EPILOGUE-CHARACTER-01','recordedAtUtc':now,'status':'REQUIRES CORRECTIONS; no EPI rules adopted','returnArchive':info(A/'DD_Cosmology_Epilogue_Character_01_Return_01.zip'),'sourceCheck':info(A/'COSMOLOGY_EPILOGUE_CHARACTER_01_RETURN_SOURCE_CHECK_01.json'),'reviewedFiles':[info(source/n) for n in ['REGISTER.json','EPILOGUE_CHARACTER_MODEL.json','PLAYER_CHAPTER.md','DIRECTOR_CHAPTER.md','CASEBOOK.json','VERDICT.md']],'scopeRead':'Complete model including all17class rows,7motifs,7virtues,7blessings,7tests,3Sentinel examples; both chapters and all51case procedures read. Source bindings verified separately.','issues':ISSUES,'proposedReplacementPuzzleTruthTable':truth,'sourceInformationDeleted':0,'newRulesAdopted':False,'runtimeTestsExecuted':0,'humanPlaytested':False,'wholeGameApproved':False}))
    root.mkdir();(root/'SEMANTIC_AUDIT.json').write_bytes(audit.read_bytes())
    (root/'SOURCE_CHECK.json').write_bytes((A/'COSMOLOGY_EPILOGUE_CHARACTER_01_RETURN_SOURCE_CHECK_01.json').read_bytes())
    request='''Please correct the EPI-01–07 first return. Thank you for the full draft; its preserved source distinctions and seven selected Base passives are useful. Local verification found365passing source/file/location checks and1bad Bard citation, plus the12concrete semantic correction areas EC01–EC12 in SEMANTIC_AUDIT.json. The first return is preserved unchanged and has NOT been adopted.

Read every EC issue and required resolution. In particular restore source Transition halving while limiting the eligible active-work domain; make Sorrow and Law actually usable; bind Warrior to the existing permanent class key; use a wearer-owned mask charge ledger; preserve duration endpoints; finish all7tests; supply a logically sound lamp puzzle; complete actual threshold/return/interlude rules; correct arithmetic; and make the player/Director chapters operationally identical to the model. Do not treat a table row count or a list of scene IDs as evidence of completed gameplay.

Use the original60frozen sources already supplied, not the correction archive as a substitute source corpus. The original60source bindings remain exact and unchanged. Local suggestions are concrete NEW proposals for your review, not owner changes to cosmological canon. Explain a different chosen repair when warranted, but resolve the actual defects rather than marking them future work. No epoch/identity/pending-spell/EPI08–17 adoption. No source deletion or runtime/human/balance/whole-game/publication approval.

Return one revised complete eight-file archive named DD_Cosmology_Epilogue_Character_01_Return_Revised.zip, with the same8filenames and original60source hashes. Do not return only patch prose. Preserve all7EPIIDs,17class rows and51existing case IDs (correct their content) and append actual additional cases needed to exercise the repairs. In REGISTER.json add correctionDispositions mapping EC01–EC12 to exact corrected model paths/case IDs and explanation. Regenerate player/Director chapters, verdict and output manifest from the final coherent candidate. Source citations must use valid exact locations. Ensure numerical and clock examples agree; do not call authored examples runtime tests. Provide the archive link and a short candid summary when complete.
'''
    (root/'REQUEST.txt').write_text(request,encoding='utf-8',newline='\n')
    bindings=[]
    for p in sorted(root.iterdir()):bindings.append({'path':p.name,'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
    (root/'MANIFEST.json').write_bytes(encoded({'reviewId':'COSMOLOGY-EPILOGUE-CHARACTER-01-EC','files':bindings}))
    with ZipFile(archive,'w',ZIP_DEFLATED) as z:
        for p in sorted(root.iterdir()):z.write(p,p.name)
    print(json.dumps({'audit':info(audit),'correctionArchive':info(archive),'issues':len(ISSUES),'newRulesAdopted':False},ensure_ascii=False))

if __name__=='__main__':main()
